35	func Tally(proposal *Proposal) string {
36		if proposal.State != "voting" {
37			return proposal.State
38		}
39		turnout := proposal.ForVotes + proposal.AgainstVotes
40		if turnout < proposal.Quorum {
41			return "rejected"
42		}
43		if proposal.ForVotes > proposal.AgainstVotes {
44			return "passed"
45		}
46		return "rejected"
47	}
