1	package govflow
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7	)
8	
9	// 投票提案相关错误。
10	var (
11		// ErrInvalidProposal：创建投票提案的参数非法（编号/成员/权重/时间/委托等）。
12		ErrInvalidProposal = errors.New("invalid voting proposal")
13		// ErrProposalNotFound 见 store.go。
14		// ErrProposalConflict：同编号提案已存在但内容或来源不同，或重复投票选择不同。
15		// ErrVoteRejected：投票被拒绝（时间窗口外、投票人无资格等）。
16		ErrVoteRejected = errors.New("vote rejected")
17		// ErrTallyRejected：计票被拒绝（截止时刻未到）。
18		ErrTallyRejected = errors.New("tally rejected")
19	)
20	
21	// ---- 输入与对外视图 ----
22	
23	// VoteMember 是创建投票提案时提交的一名成员及其原始权重。
24	type VoteMember struct {
25		ID     string `json:"id"`
26		Weight int64  `json:"weight"`
27	}
28	
29	// Delegation 表示 From 把投票权委托给 To。委托可以继续转交，
30	// 最终未再委托的人代表沿途所有成员投票。
31	type Delegation struct {
32		From string `json:"from"`
33		To   string `json:"to"`
34	}
35	
36	// CreateVoteInput 是创建一项投票提案的完整输入。
37	type CreateVoteInput struct {
38		ID          string
39		Members     []VoteMember
40		Delegations []Delegation
41		Quorum      int64
42		StartAt     int64
43		Deadline    int64
44		TimelockEnd int64
45		Actions     []string
46	}
47	
48	// MemberView 是查询时展示的一名成员：委托路径、最终代表与原始权重。
49	type MemberView struct {
50		ID       string   `json:"id"`
51		Weight   int64    `json:"weight"`
52		Path     []string `json:"path"`      // 从本人到最终代表的完整编号链（含首尾）
53		Delegate string   `json:"delegate"`  // 最终代表
54		Direct   string   `json:"direct_to"` // 直接委托对象；未委托为空串
55	}
56	
57	// BallotView 是查询时展示的一张已投出的票。
58	type BallotView struct {
59		Representative string `json:"representative"`
60		Weight         int64  `json:"weight"`
61		Support        bool   `json:"support"`
62		VotedAt        int64  `json:"voted_at"`
63	}
64	
65	// TallyResultView 是首次计票结论的查询视图；尚未计票时为 nil。
66	type TallyResultView struct {
67		ForWeight     int64 `json:"for_weight"`
68		AgainstWeight int64 `json:"against_weight"`
69		Turnout       int64 `json:"turnout"`
70		Quorum        int64 `json:"quorum"`
71		Passed        bool  `json:"passed"`
72		TalliedAt     int64 `json:"tallied_at"`
73	}
74	
75	// VoteProposalView 是一项投票提案的完整对外视图。
76	type VoteProposalView struct {
77		ID          string           `json:"id"`
78		Source      string           `json:"source"` // vote
79		State       string           `json:"state"`  // voting / passed / rejected / executed
80		Quorum      int64            `json:"quorum"`
81		StartAt     int64            `json:"start_at"`
82		Deadline    int64            `json:"deadline"`
83		TimelockEnd int64            `json:"timelock_end"`
84		Actions     []string         `json:"actions"`
85		TotalWeight int64            `json:"total_weight"`
86		Members     []MemberView     `json:"members"`
87		Ballots     []BallotView     `json:"ballots"`
88		Tally       *TallyResultView `json:"tally,omitempty"`
89	}
90	
91	// ---- 磁盘结构（JSON，版本仍为 1） ----
92	
93	type storedMember struct {
94		ID     string `json:"id"`
95		Weight int64  `json:"weight"`
96	}
97	
98	type storedDelegation struct {
99		From string `json:"from"`
100		To   string `json:"to"`
101	}
102	
103	type storedBallot struct {
104		Representative string `json:"representative"`
105		Weight         int64  `json:"weight"`
106		Support        bool   `json:"support"`
107		VotedAt        int64  `json:"voted_at"`
108	}
109	
110	type storedTally struct {
111		ForWeight     int64 `json:"for_weight"`
112		AgainstWeight int64 `json:"against_weight"`
113		TalliedAt     int64 `json:"tallied_at"`
114	}
115	
116	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
117	// 动作文本与顺序原样保存（顺序影响相等性）。
118	type storedVoteProposal struct {
119		ID          string             `json:"id"`
120		State       string             `json:"state"`
121		Members     []storedMember     `json:"members"`
122		Delegations []storedDelegation `json:"delegations"`
123		Quorum      int64              `json:"quorum"`
124		StartAt     int64              `json:"start_at"`
125		Deadline    int64              `json:"deadline"`
126		TimelockEnd int64              `json:"timelock_end"`
127		Actions     []string           `json:"actions"`
128		Ballots     []storedBallot     `json:"ballots"`
129		Tally       *storedTally       `json:"tally,omitempty"`
130	}
131	
132	// ---- 校验与派生 ----
133	
134	type proposalSpec struct {
135		members  []VoteMember
136		weights  map[string]int64
137		delegate map[string]string // 直接委托对象
138		pathOf   map[string][]string
139		headOf   map[string]string // 最终代表
140		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
141		total    int64
142	}
143	
144	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
145	// 任何非法条件都返回错误，调用方必须整项拒绝。
146	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
147		if in.ID == "" {
148			return nil, invalidProposal("proposal id must not be empty")
149		}
150		if len(in.Members) == 0 {
151			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
152		}
153		weights := make(map[string]int64, len(in.Members))
154		order := make([]string, 0, len(in.Members))
155		for _, m := range in.Members {
156			if m.ID == "" {
157				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
158			}
159			if _, dup := weights[m.ID]; dup {
160				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
161			}
162			if m.Weight <= 0 {
163				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
164			}
165			weights[m.ID] = m.Weight
166			order = append(order, m.ID)
167		}
168	
169		// 总权重必须在 int64 范围内（各权重已为正）。
170		var total int64
171		for _, m := range in.Members {
172			sum, ok := addInt64(total, m.Weight)
173			if !ok {
174				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
175			}
176			total = sum
177		}
178	
179		if in.Quorum < 1 || in.Quorum > total {
180			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
181		}
182		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
183			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
184				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
185		}
186	
187		delegate := make(map[string]string, len(in.Delegations))
188		for _, d := range in.Delegations {
189			if d.From == "" || d.To == "" {
190				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
191			}
192			if _, ok := weights[d.From]; !ok {
193				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
194			}
195			if _, ok := weights[d.To]; !ok {
196				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
197			}
198			if d.From == d.To {
199				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
200			}
201			if _, dup := delegate[d.From]; dup {
202				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
203			}
204			delegate[d.From] = d.To
205		}
206	
207		// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
208		// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
209		// 所以该遍历必然终止。
210		// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
211		// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
212		// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
213		pathOf := make(map[string][]string, len(weights))
214		headOf := make(map[string]string, len(weights))
215		for _, id := range order {
216			if _, done := headOf[id]; done {
217				continue
218			}
219			chain := []string{id}
220			onChain := map[string]int{id: 0}
221			cur := id
222			for {
223				next, has := delegate[cur]
224				if !has {
225					break // cur 即未再委托的最终代表
226				}
227				if pos, cyc := onChain[next]; cyc {
228					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
229				}
230				if resolved, ok := pathOf[next]; ok {
231					// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
232					chain = append(chain, resolved...)
233					cur = resolved[len(resolved)-1]
234					break
235				}
236				chain = append(chain, next)
237				onChain[next] = len(chain) - 1
238				cur = next
239			}
240			head := cur
241			// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
242			// 后缀成员均已登记，这里只补齐尚未解析的成员。
243			for i := 0; i < len(chain); i++ {
244				member := chain[i]
245				if _, ok := headOf[member]; !ok {
246					pathOf[member] = append([]string(nil), chain[i:]...)
247					headOf[member] = head
248				}
249			}
250		}
251	
252		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
253		groupW := make(map[string]int64)
254		for _, id := range order {
255			head := headOf[id]
256			sum, ok := addInt64(groupW[head], weights[id])
257			if !ok {
258				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
259			}
260			groupW[head] = sum
261		}
262	
263		return &proposalSpec{
264			members:  append([]VoteMember(nil), in.Members...),
265			weights:  weights,
266			delegate: delegate,
267			pathOf:   pathOf,
268			headOf:   headOf,
269			groupW:   groupW,
270			total:    total,
271		}, nil
272	}
273	
274	func invalidProposal(format string, args ...any) error {
275		return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
276	}
277	
278	// proposalsEqual 判断重试内容是否与已存提案逐项相同。
279	// 成员与委托的输入次序不影响比较；动作文本与顺序必须一致。
280	func proposalsEqual(stored *storedVoteProposal, in *CreateVoteInput, spec *proposalSpec) bool {
281		if stored.Quorum != in.Quorum || stored.StartAt != in.StartAt ||
282			stored.Deadline != in.Deadline || stored.TimelockEnd != in.TimelockEnd {
283			return false
284		}
285		if !sameActions(stored.Actions, in.Actions) {
286			return false
287		}
288		if len(stored.Members) != len(in.Members) {
289			return false
290		}
291		for _, m := range stored.Members {
292			if w, ok := spec.weights[m.ID]; !ok || w != m.Weight {
293				return false
294			}
295		}
296		if len(stored.Delegations) != len(in.Delegations) {
297			return false
298		}
299		for _, d := range stored.Delegations {
300			to, ok := spec.delegate[d.From]
301			if !ok || to != d.To {
302				return false
303			}
304		}
305		return true
306	}
307	
308	// ---- 存储操作 ----
309	
310	// CreateVoteProposal 创建一项投票提案。
311	// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
312	// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
313	// 非法条件整项拒绝，不落盘任何部分变化。
314	func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
315		spec, err := validateProposalInput(in)
316		if err != nil {
317			return nil, false, err
318		}
319		commit, err := s.begin()
320		if err != nil {
321			return nil, false, err
322		}
323		defer commit()
324	
325		state, err := s.loadLocked()
326		if err != nil {
327			return nil, false, err
328		}
329		if existing, ok := state.VoteProposals[in.ID]; ok {
330			if !proposalsEqual(existing, in, spec) {
331				return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
332			}
333			v := voteProposalView(existing)
334			return v, true, nil
335		}
336		if _, ok := state.Proposals[in.ID]; ok {
337			// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
338			return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
339		}
340	
341		stored := &storedVoteProposal{
342			ID:          in.ID,
343			State:       "voting",
344			Members:     make([]storedMember, 0, len(in.Members)),
345			Delegations: make([]storedDelegation, 0, len(in.Delegations)),
346			Quorum:      in.Quorum,
347			StartAt:     in.StartAt,
348			Deadline:    in.Deadline,
349			TimelockEnd: in.TimelockEnd,
350			Actions:     copyActions(in.Actions),
351			Ballots:     []storedBallot{},
352		}
353		for _, m := range in.Members {
354			stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
355		}
356		for _, d := range in.Delegations {
357			stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
358		}
359		state.VoteProposals[in.ID] = stored
360		if err := s.commitLocked(state); err != nil {
361			return nil, false, err
362		}
363		return voteProposalView(stored), false, nil
364	}
365	
366	func voteReject(reason string) error {
367		return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
368	}
369	
370	func tallyReject(reason string) error {
371		return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
372	}
373	
374	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
375	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
376	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
377	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
378	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
379		if voter == "" {
380			return nil, voteReject("voter id must not be empty")
381		}
382		commit, err := s.begin()
383		if err != nil {
384			return nil, err
385		}
386		defer commit()
387	
388		state, err := s.loadLocked()
389		if err != nil {
390			return nil, err
391		}
392		p, ok := state.VoteProposals[id]
393		if !ok {
394			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
395		}
396		spec, verr := specOf(p)
397		if verr != nil {
398			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
399		}
400		if _, member := spec.weights[voter]; !member {
401			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
402		}
403		if spec.headOf[voter] != voter {
404			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
405		}
406		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
407		// 改投另一选择报冲突，绝不静默覆盖。
408		for i := range p.Ballots {
409			if p.Ballots[i].Representative == voter {
410				if p.Ballots[i].Support != support {
411					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
412						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
413				}
414				b := p.Ballots[i]
415				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
416			}
417		}
418		if p.Tally != nil {
419			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
420		}
421		if now < p.StartAt || now >= p.Deadline {
422			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
423		}
424	
425		p.Ballots = append(p.Ballots, storedBallot{
426			Representative: voter,
427			Weight:         spec.groupW[voter],
428			Support:        support,
429			VotedAt:        now,
430		})
431		if err := s.commitLocked(state); err != nil {
432			return nil, err
433		}
434		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
435	}
436	
437	func voteChoice(support bool) string {
438		if support {
439			return "for"
440		}
441		return "against"
442	}
443	
444	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
445	// 且赞成严格多于反对才通过。未投权重不计入参与量。
446	// 计票只确定状态，不转账；再次计票始终返回首次结论。
447	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
448		commit, err := s.begin()
449		if err != nil {
450			return nil, err
451		}
452		defer commit()
453	
454		state, err := s.loadLocked()
455		if err != nil {
456			return nil, err
457		}
458		p, ok := state.VoteProposals[id]
459		if !ok {
460			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
461		}
462		if p.Tally != nil {
463			return storedTallyResult(p), nil
464		}
465		if now < p.Deadline {
466			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
467		}
468	
469		spec, verr := specOf(p)
470		if verr != nil {
471			return nil, verr
472		}
473		var forW, againstW int64
474		seen := map[string]bool{}
475		for _, b := range p.Ballots {
476			if seen[b.Representative] {
477				return nil, fmt.Errorf("%w: proposal %s has duplicate stored ballot for %q", ErrStateCorrupt, id, b.Representative)
478			}
479			seen[b.Representative] = true
480			if b.Weight != spec.groupW[b.Representative] {
481				return nil, fmt.Errorf("%w: proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
482					ErrStateCorrupt, id, b.Representative, b.Weight, spec.groupW[b.Representative])
483			}
484			if b.Support {
485				sum, ok := addInt64(forW, b.Weight)
486				if !ok {
487					return nil, fmt.Errorf("%w: proposal %s vote weights overflow int64", ErrStateCorrupt, id)
488				}
489				forW = sum
490			} else {
491				sum, ok := addInt64(againstW, b.Weight)
492				if !ok {
493					return nil, fmt.Errorf("%w: proposal %s vote weights overflow int64", ErrStateCorrupt, id)
494				}
495				againstW = sum
496			}
497		}
498	
499		turnout, _ := addInt64(forW, againstW) // 不超过总权重
500		passed := turnout >= p.Quorum && forW > againstW
501		p.Tally = &storedTally{ForWeight: forW, AgainstWeight: againstW, TalliedAt: now}
502		if passed {
503			p.State = "passed"
504		} else {
505			p.State = "rejected"
506		}
507		if err := s.commitLocked(state); err != nil {
508			return nil, err
509		}
510		return storedTallyResult(p), nil
511	}
512	
513	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
514	// Passed 按票数与法定人数重算：提案后续执行（executed）不改变首次结论。
515	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
516		if p.Tally == nil {
517			return nil
518		}
519		turnout := p.Tally.ForWeight + p.Tally.AgainstWeight
520		return &TallyResultView{
521			ForWeight:     p.Tally.ForWeight,
522			AgainstWeight: p.Tally.AgainstWeight,
523			Turnout:       turnout,
524			Quorum:        p.Quorum,
525			Passed:        p.Tally.ForWeight > p.Tally.AgainstWeight && turnout >= p.Quorum,
526			TalliedAt:     p.Tally.TalliedAt,
527		}
528	}
529	
530	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
531	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
532		state, err := s.readState()
533		if err != nil {
534			return nil, false, err
535		}
536		p, ok := state.VoteProposals[id]
537		if !ok {
538			return nil, false, nil
539		}
540		return voteProposalView(p), true, nil
541	}
542	
543	// VoteProposals 返回全部投票提案，按编号排序。
544	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
545		state, err := s.readState()
546		if err != nil {
547			return nil, err
548		}
549		return voteProposalViews(state), nil
550	}
551	
552	func voteProposalViews(state *storedState) []*VoteProposalView {
553		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
554		for _, p := range state.VoteProposals {
555			out = append(out, voteProposalView(p))
556		}
557		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
558		return out
559	}
560	
561	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
562		spec, err := specOf(p)
563		if err != nil {
564			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
565			panic("govflow: building view of corrupt proposal: " + err.Error())
566		}
567		members := make([]MemberView, 0, len(p.Members))
568		for _, m := range p.Members { // 保持成员提交顺序
569			mv := MemberView{
570				ID:       m.ID,
571				Weight:   m.Weight,
572				Path:     append([]string(nil), spec.pathOf[m.ID]...),
573				Delegate: spec.headOf[m.ID],
574			}
575			if to, ok := spec.delegate[m.ID]; ok {
576				mv.Direct = to
577			}
578			members = append(members, mv)
579		}
580		ballots := make([]BallotView, 0, len(p.Ballots))
581		for _, b := range p.Ballots { // 保持首次投票先后顺序
582			ballots = append(ballots, BallotView{
583				Representative: b.Representative,
584				Weight:         b.Weight,
585				Support:        b.Support,
586				VotedAt:        b.VotedAt,
587			})
588		}
589		v := &VoteProposalView{
590			ID:          p.ID,
591			Source:      "vote",
592			State:       p.State,
593			Quorum:      p.Quorum,
594			StartAt:     p.StartAt,
595			Deadline:    p.Deadline,
596			TimelockEnd: p.TimelockEnd,
597			Actions:     copyActions(p.Actions),
598			TotalWeight: spec.total,
599			Members:     members,
600			Ballots:     ballots,
601		}
602		if p.Tally != nil {
603			v.Tally = storedTallyResult(p)
604		}
605		return v
606	}
607	
608	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
609	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
610		in := &CreateVoteInput{
611			ID:          p.ID,
612			Quorum:      p.Quorum,
613			StartAt:     p.StartAt,
614			Deadline:    p.Deadline,
615			TimelockEnd: p.TimelockEnd,
616			Actions:     p.Actions,
617		}
618		in.Members = make([]VoteMember, len(p.Members))
619		for i, m := range p.Members {
620			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
621		}
622		in.Delegations = make([]Delegation, len(p.Delegations))
623		for i, d := range p.Delegations {
624			in.Delegations[i] = Delegation{From: d.From, To: d.To}
625		}
626		return validateProposalInput(in)
627	}
628	
629	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
630	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
631	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
632	func validateVoteProposals(state *storedState) error {
633		for key, p := range state.VoteProposals {
634			if p == nil {
635				return fmt.Errorf("voting proposal %q is empty", key)
636			}
637			if p.ID != key || p.ID == "" {
638				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
639			}
640			if _, collide := state.Proposals[p.ID]; collide {
641				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
642			}
643			switch p.State {
644			case "voting", "passed", "rejected", "executed":
645			default:
646				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
647			}
648			spec, err := specOf(p)
649			if err != nil {
650				return err
651			}
652	
653			// 票据明细：代表必须是最终代表，票重必须等于名单与委托归集出的权重。
654			seenReps := map[string]bool{}
655			var ballotFor, ballotAgainst int64
656			for i, b := range p.Ballots {
657				if b.Representative == "" {
658					return fmt.Errorf("voting proposal %q ballot %d has empty representative", p.ID, i)
659				}
660				if spec.headOf[b.Representative] != b.Representative {
661					return fmt.Errorf("voting proposal %q ballot %d: %q is not a final representative", p.ID, i, b.Representative)
662				}
663				if seenReps[b.Representative] {
664					return fmt.Errorf("voting proposal %q has duplicate ballot for representative %q", p.ID, b.Representative)
665				}
666				seenReps[b.Representative] = true
667				if b.Weight != spec.groupW[b.Representative] {
668					return fmt.Errorf("voting proposal %q ballot weight for %q is %d, roster/delegations yield %d",
669						p.ID, b.Representative, b.Weight, spec.groupW[b.Representative])
670				}
671				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
672					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
673						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
674				}
675				if b.Support {
676					sum, ok := addInt64(ballotFor, b.Weight)
677					if !ok {
678						return fmt.Errorf("voting proposal %q ballot weights overflow int64", p.ID)
679					}
680					ballotFor = sum
681				} else {
682					sum, ok := addInt64(ballotAgainst, b.Weight)
683					if !ok {
684						return fmt.Errorf("voting proposal %q ballot weights overflow int64", p.ID)
685					}
686					ballotAgainst = sum
687				}
688			}
689	
690			switch {
691			case p.Tally == nil:
692				if p.State != "voting" {
693					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
694				}
695			default:
696				if p.State == "voting" {
697					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
698				}
699				if p.Tally.TalliedAt < p.Deadline {
700					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
701				}
702				if p.Tally.ForWeight != ballotFor || p.Tally.AgainstWeight != ballotAgainst {
703					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
704						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, ballotFor, ballotAgainst)
705				}
706				turnout := ballotFor + ballotAgainst
707				passedNow := turnout >= p.Quorum && ballotFor > ballotAgainst
708				if passedNow != (p.State == "passed" || p.State == "executed") {
709					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
710				}
711			}
712		}
713		return nil
714	}
