15	// buildCLI 将命令行编译到临时目录，供跨进程测试使用。仅使用标准库，离线可编译。
16	func buildCLI(t *testing.T) string {
17		t.Helper()
18		binary := filepath.Join(t.TempDir(), "govflow")
19		cmd := exec.Command("go", "build", "-o", binary, "./cmd/govflow")
20		// 测试工作目录为模块下的 govflow/，仓库根目录在上一层。
21		cmd.Dir = ".."
22		var out bytes.Buffer
23		cmd.Stderr = &out
24		if err := cmd.Run(); err != nil {
25			t.Fatalf("build cli: %v\n%s", err, out.String())
26		}
27		return binary
28	}
29	
30	func runCLI(t *testing.T, binary, state string, args ...string) (stdout, stderr string, code int) {
31		t.Helper()
32		// main 以第一个参数作为子命令，--state 必须位于子命令之后。
33		full := append([]string{args[0], "--state", state}, args[1:]...)
34		cmd := exec.Command(binary, full...)
35		var so, se bytes.Buffer
36		cmd.Stdout = &so
37		cmd.Stderr = &se
38		err := cmd.Run()
39		if ee, ok := err.(*exec.ExitError); ok {
40			code = ee.ExitCode()
41		} else if err != nil {
42			t.Fatalf("run cli %v: %v", args, err)
43		}
44		return so.String(), se.String(), code
45	}
