47	// TestCrossProcessSameProposal：多个进程同时执行同一提案，
48	// 只能有一份成功凭据；其余进程拿到同一份凭据（重试语义），不得二次扣款。
49	func TestCrossProcessSameProposal(t *testing.T) {
50		binary := buildCLI(t)
51		state := filepath.Join(t.TempDir(), "treasury.json")
52		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
53			t.Fatal("init failed")
54		}
55		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-1",
56			"--timelock", "100", "--action", "transfer:audits:250"); code != 0 {
57			t.Fatal("register failed")
58		}
59	
60		const n = 16
61		var wg sync.WaitGroup
62		codes := make([]int, n)
63		outputs := make([]string, n)
64		start := make(chan struct{})
65		for i := 0; i < n; i++ {
66			wg.Add(1)
67			go func(i int) {
68				defer wg.Done()
69				<-start
70				so, se, code := runCLI(t, binary, state, "execute", "--id", "gip-1",
71					"--now", strconv.Itoa(100+i), "--json")
72				codes[i] = code
73				outputs[i] = so + se
74			}(i)
75		}
76		close(start)
77		wg.Wait()
78	
79		for i, code := range codes {
80			if code != 0 {
81				t.Fatalf("process %d exited %d: %s", i, code, outputs[i])
82			}
83			// 每个进程看到的首次执行时间都必须是 100（最早请求未必胜出，但凭据唯一）。
84			if !strings.Contains(outputs[i], `"executed_at"`) {
85				t.Fatalf("process %d got no receipt: %s", i, outputs[i])
86			}
87		}
88		so, _, code := runCLI(t, binary, state, "receipts", "--json")
89		if code != 0 {
90			t.Fatal("receipts failed")
91		}
92		if strings.Count(so, `"proposal_id"`) != 1 {
93			t.Fatalf("expected exactly one receipt, got:\n%s", so)
94		}
95		if so2, _, _ := runCLI(t, binary, state, "balances", "--json"); !strings.Contains(so2, `"treasury": 750`) {
96			t.Fatalf("treasury must be 750 after single execution:\n%s", so2)
97		}
98	}
