100	// TestCrossProcessDifferentProposals：40 个进程各花 10，资金库只有 100，
101	// 必须恰好 10 个成功，且所有判断基于实际已提交余额。
102	func TestCrossProcessDifferentProposals(t *testing.T) {
103		binary := buildCLI(t)
104		state := filepath.Join(t.TempDir(), "treasury.json")
105		if _, _, code := runCLI(t, binary, state, "init", "--balance", "100"); code != 0 {
106			t.Fatal("init failed")
107		}
108		const n = 40
109		for i := 0; i < n; i++ {
110			if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-"+itoa(i),
111				"--timelock", "0", "--action", "transfer:acct:10"); code != 0 {
112				t.Fatalf("register %d failed", i)
113			}
114		}
115	
116		var wg sync.WaitGroup
117		successes := make(chan int, n)
118		failures := make(chan string, n)
119		start := make(chan struct{})
120		for i := 0; i < n; i++ {
121			wg.Add(1)
122			go func(i int) {
123				defer wg.Done()
124				<-start
125				_, se, code := runCLI(t, binary, state, "execute", "--id", "gip-"+itoa(i), "--now", "0")
126				if code == 0 {
127					successes <- 1
128				} else {
129					failures <- se
130				}
131			}(i)
132		}
133		close(start)
134		wg.Wait()
135		close(successes)
136		close(failures)
137		got := 0
138		for range successes {
139			got++
140		}
141		for msg := range failures {
142			if !strings.Contains(msg, "insufficient") {
143				t.Fatalf("unexpected failure reason: %s", msg)
144			}
145		}
146		if got != 10 {
147			t.Fatalf("cross-process successes=%d, want 10", got)
148		}
149	
150		so, _, _ := runCLI(t, binary, state, "balances", "--json")
151		if !strings.Contains(so, `"treasury": 0`) || !strings.Contains(so, `"acct": 100`) {
152			t.Fatalf("final balances wrong:\n%s", so)
153		}
154		so, _, _ = runCLI(t, binary, state, "receipts", "--json")
155		if strings.Count(so, `"proposal_id"`) != 10 {
156			t.Fatalf("expected 10 receipts, got:\n%s", so)
157		}
158	}
