234	// TestCrossProcessVotingLifecycle：通过 CLI 跨进程完成创建→委托投票→计票→执行，
235	// 并验证重复创建/投票/计票的幂等与冲突语义。
236	func TestCrossProcessVotingLifecycle(t *testing.T) {
237		binary := buildCLI(t)
238		state := filepath.Join(t.TempDir(), "treasury.json")
239		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
240			t.Fatal("init failed")
241		}
242		create := []string{"create-vote", "--id", "gip-vote-1",
243			"--member", "alice:300", "--member", "bob:200", "--member", "carol:100", "--member", "dave:400",
244			"--delegate", "bob:alice", "--delegate", "carol:alice",
245			"--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300",
246			"--action", "transfer:audits:100"}
247		if _, se, code := runCLI(t, binary, state, create...); code != 0 {
248			t.Fatalf("create-vote failed: %s", se)
249		}
250		// 成员与委托换序的完全相同重试：成功且不改动状态。
251		retry := []string{"create-vote", "--id", "gip-vote-1",
252			"--member", "dave:400", "--member", "carol:100", "--member", "bob:200", "--member", "alice:300",
253			"--delegate", "carol:alice", "--delegate", "bob:alice",
254			"--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300",
255			"--action", "transfer:audits:100"}
256		if _, se, code := runCLI(t, binary, state, retry...); code != 0 {
257			t.Fatalf("identical create retry should succeed: %s", se)
258		}
259		// 内容不同的重试冲突（多一个动作，动作按原文及顺序比较）。
260		conflict := append(append([]string{}, create...), "--action", "transfer:legal:1")
261		if _, _, code := runCLI(t, binary, state, conflict...); code != 1 {
262			t.Fatalf("conflicting create should exit 1, got %d", code)
263		}
264		// register 不能占用投票提案编号。
265		if _, se, code := runCLI(t, binary, state, "register", "--id", "gip-vote-1",
266			"--timelock", "300", "--action", "transfer:audits:100"); code != 1 {
267			t.Fatalf("register over voting id should fail: %s", se)
268		}
269	
270		// 委托出去的成员投票被拒；非名单成员被拒。
271		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
272			"--voter", "bob", "--choice", "for", "--now", "150"); code != 1 || !strings.Contains(se, "delegated") {
273			t.Fatalf("delegated member vote code=%d: %s", code, se)
274		}
275		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
276			"--voter", "ghost", "--choice", "for", "--now", "150"); code != 1 || !strings.Contains(se, "not on the member roster") {
277			t.Fatalf("non-member vote code=%d: %s", code, se)
278		}
279	
280		// 代表 alice（归集 600）赞成；相同选择跨进程重试返回首次时间。
281		if so, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
282			"--voter", "alice", "--choice", "for", "--now", "120", "--json"); code != 0 ||
283			!strings.Contains(so, `"weight": 600`) {
284			t.Fatalf("alice vote code=%d so=%s se=%s", code, so, se)
285		}
286		if so, _, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
287			"--voter", "alice", "--choice", "for", "--now", "180", "--json"); code != 0 ||
288			!strings.Contains(so, `"voted_at": 120`) {
289			t.Fatalf("identical vote retry must return first record: %s", so)
290		}
291		// 改投冲突。
292		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
293			"--voter", "alice", "--choice", "against", "--now", "120"); code != 1 ||
294			!strings.Contains(se, "changing the vote") {
295			t.Fatalf("change vote code=%d: %s", code, se)
296		}
297	
298		// 截止前计票拒绝。
299		if _, se, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1", "--now", "199"); code != 1 ||
300			!strings.Contains(se, "still open") {
301			t.Fatalf("early tally code=%d: %s", code, se)
302		}
303		// 截止时刻计票：600 赞成、0 反对、达到法定人数 => passed。
304		if so, se, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
305			"--now", "200", "--json"); code != 0 || !strings.Contains(so, `"passed": true`) {
306			t.Fatalf("tally code=%d so=%s se=%s", code, so, se)
307		}
308		// 计票后窗口内新票也拒绝。
309		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
310			"--voter", "dave", "--choice", "against", "--now", "150"); code != 1 ||
311			!strings.Contains(se, "already been tallied") {
312			t.Fatalf("post-tally vote code=%d: %s", code, se)
313		}
314		// 再次计票返回首次时间。
315		if so, _, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
316			"--now", "999", "--json"); code != 0 || !strings.Contains(so, `"tallied_at": 200`) {
317			t.Fatalf("repeat tally: %s", so)
318		}
319	
320		// 通过后直接由 execute 执行，无需再登记；时间锁未到拒绝。
321		if _, _, code := runCLI(t, binary, state, "execute", "--id", "gip-vote-1", "--now", "299"); code != 1 {
322			t.Fatalf("execute before timelock should fail")
323		}
324		if _, _, code := runCLI(t, binary, state, "execute", "--id", "gip-vote-1", "--now", "300"); code != 0 {
325			t.Fatalf("execute voted proposal failed")
326		}
327		if so, _, _ := runCLI(t, binary, state, "balances", "--json"); !strings.Contains(so, `"treasury": 900`) ||
328			!strings.Contains(so, `"audits": 100`) {
329			t.Fatalf("balances after voted execution:\n%s", so)
330		}
331		// 已执行提案不退回通过：再次执行返回首次凭据。
332		if so, _, _ := runCLI(t, binary, state, "execute", "--id", "gip-vote-1",
333			"--now", "9999", "--json"); !strings.Contains(so, `"executed_at": 300`) {
334			t.Fatalf("re-execute should return first receipt: %s", so)
335		}
336		// 查询包含逐票明细、委托路径与已执行状态。
337		so, _, _ := runCLI(t, binary, state, "proposal", "--id", "gip-vote-1", "--json")
338		if !strings.Contains(so, `"state": "executed"`) ||
339			!strings.Contains(so, `"representative": "alice"`) ||
340			!pathJSONRe.MatchString(so) {
341			t.Fatalf("proposal query missing delegation path/ballot/state:\n%s", so)
342		}
343	}
344	
345	var pathJSONRe = regexp.MustCompile(`"path": \[\s+"bob",\s+"alice"\s+\]`)
