347	// TestCrossProcessConcurrentTally：多进程同时计票，结论只产生一次且不追加任何记录。
348	func TestCrossProcessConcurrentTally(t *testing.T) {
349		binary := buildCLI(t)
350		state := filepath.Join(t.TempDir(), "treasury.json")
351		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
352			t.Fatal("init failed")
